import { create_list_edit_delete_work_shift_timings } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    workshiftDeletion: Boolean,
    workshiftData: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    workshiftDeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_Entity() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_work_shift_timings, {
          input: {
            action_type: "DELETE",
            work_shift_timings_id: this.workshiftData.work_shift_timings_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_work_shift_timings);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
